package application.domain.services.order;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport; import application.domain.exceptions.*; import java.util.*;
public class UpdateOrderStatusService implements UpdateOrderStatusUseCase { private final OrderRepositoryPort orders; private final OperationAuditPort audit; public UpdateOrderStatusService(OrderRepositoryPort o,OperationAuditPort a){orders=o;audit=a;}
 public Order updateOrderStatus(User actor,String id,DomainTypes.OrderStatus status){ServiceSupport.role(actor,"ADMIN","EMPLOYEE","SELLER");Order o=ServiceSupport.required(orders.findById(id),"Order",id);if(!valid(o.getStatus(),status))throw new DomainRuleException("Invalid order status transition");o.changeStatus(status);orders.update(o);audit.record(actor,"UPDATE_ORDER_STATUS",id,Map.of("status",status.name()));return o;}
 private boolean valid(DomainTypes.OrderStatus a,DomainTypes.OrderStatus b){if(a==b)return true;return switch(a){case CREATED->b==DomainTypes.OrderStatus.PENDING_PAYMENT||b==DomainTypes.OrderStatus.CANCELLED;case PENDING_PAYMENT->b==DomainTypes.OrderStatus.PAID||b==DomainTypes.OrderStatus.CANCELLED;case PAID->b==DomainTypes.OrderStatus.PROCESSING||b==DomainTypes.OrderStatus.CANCELLED;case PROCESSING->b==DomainTypes.OrderStatus.SHIPPED||b==DomainTypes.OrderStatus.CANCELLED;case SHIPPED->b==DomainTypes.OrderStatus.DELIVERED;case DELIVERED->b==DomainTypes.OrderStatus.RETURN_REQUESTED;case RETURN_REQUESTED->b==DomainTypes.OrderStatus.RETURNED;case RETURNED->b==DomainTypes.OrderStatus.REFUNDED;default->false;};}
}
